    await ui.showRetired(pg_vic, true);
    await ui.refresh(pg_uma);
    expect(await ui.bulkReassign(pg_uma, [c_ada_0, c_ben_0], "Ben")).toEqual({ reassigned: 0, refused: 2 });
    await ui.refresh(pg_vic);
    expect(await ui.bulkReassign(pg_vic, [c_ada_0, c_ada_1, c_ben_0, c_cam_0], "Ben")).toEqual({ reassigned: 3, refused: 1 });
